// app/artist/layout.tsx
export default async function Layout({ children }) {
  const genres = await getGenres()
  return <><GenreNav genres={genres} />{children}</>
}

// app/artist/[username]/page.tsx
export default async function Page({ params }) {
  const artist = await getArtist((await params).username)
  return <ArtistCard artist={artist} />
}

export default async function Page({ params }) {
  const { username } = await params
  const artist = await getArtist(username)
  const albums = await getAlbums(username)
  return <Profile artist={artist} albums={albums} />
}

export default async function Page() {
  const res = await fetch('https://api.example.com/post/42')
  const data = await res.json()
  return <article>{data.title}</article>
}
